import { yupResolver } from "@hookform/resolvers/yup";
import { LoadingButton } from "@mui/lab";
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  FormControlLabel,
  FormHelperText,
  FormLabel,
  Grid,
  IconButton,
  Radio,
  RadioGroup,
  TextField,
} from "@mui/material";
import CloseIcon from "mdi-material-ui/Close";
import { useEffect, useState } from "react";
import { Controller, useForm } from "react-hook-form";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import * as yup from "yup";
import { toastError, toastSuccess } from "src/utils/utils";
import UploadIcon from "@mui/icons-material/Upload";
import "react-quill/dist/quill.snow.css";

const FileInput = ({ inputId, accept, onChange, selectedFileName, error }) => (
  <>
    <Button
      startIcon={<UploadIcon />}
      variant="contained"
      sx={{ bgcolor: "#fff", border: "1px solid #6B6B6B", color: "#000" }}
      onClick={() => document.getElementById(inputId).click()}
    >
      Choose File
    </Button>
    <input
      id={inputId}
      name={inputId}
      type="file"
      accept={accept}
      onChange={onChange}
      style={{ display: "none" }}
    />
    <FormHelperText
      variant="body2"
      sx={{ color: "#6B6B6B", marginBottom: "8px" }}
    >
      {selectedFileName || "No file chosen"}
    </FormHelperText>
    <FormHelperText
      variant="body2"
      sx={{ color: "#6B6B6B", marginBottom: "8px" }}
    >
      {error && error.message}
    </FormHelperText>
  </>
);
const validationSchema = yup.object().shape({
  //   feature: yup.string().trim().required("Please add Feature."),
  //   is_native_tools: yup.boolean(),
  //   is_plus: yup.boolean(),
});

const DialogOverviewDownload = (props) => {
  const { mode, open, toggle, dataToEdit, onSuccess, itSolutionId } = props;

  const [loading, setLoading] = useState(false);
  const [dialogTitle, setDialogTitle] = useState("");

  const {
    control,
    handleSubmit,
    reset,
    setValue,
    formState: { errors },
  } = useForm({
    defaultValues: {
      overview_pdf: "",
    },
    resolver: yupResolver(validationSchema),
    mode: "onChange",
  });

  const [selectedFileNames, setSelectedFileNames] = useState({
    overview_pdf: "",
  });

  const [ImageFile, setImageFile] = useState(null);

  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    if (selectedFile) {
      setImageFile(selectedFile);
      setSelectedFileNames({
        ...selectedFileNames,
        overview_pdf: selectedFile.name,
      });
    }
    console.log("imageFile", selectedFile);
  };
  useEffect(() => {
    console.log("image", ImageFile);
  }, [ImageFile]);
  useEffect(() => {
    if (open) {
      setLoading(false);
      setDialogTitle(mode === "add" ? "Add PDF" : "Edit PDF");
      if (mode === "edit" && dataToEdit) {
        setSelectedFileNames({
          overview_pdf: dataToEdit?.overview_pdf || "",
        });
        setImageFile(null); // Set to null or initial value
      } else {
        setSelectedFileNames({ overview_pdf: "" });
        setImageFile(null);
      }
    }
  }, [dataToEdit, mode, open, reset]);

  const onSubmit = (data) => {
    const payload = new FormData();

    if (ImageFile) {
      payload.append("overview_pdf", ImageFile);
      payload.append("sub_it_solution_list_id", itSolutionId);
    }

    setLoading(true);

    let apiInstance = null;

    if (mode === "edit") {
      apiInstance = axiosInstance.patch(
        ApiEndPoints.ITSolutionOverviewDownload.edit(dataToEdit.id),
        payload,
        {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        }
      );
    } else {
      apiInstance = axiosInstance.post(
        ApiEndPoints.ITSolutionOverviewDownload.create,
        payload,
        {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        }
      );
    }

    apiInstance
      .then((response) => response.data)
      .then((response) => {
        onSuccess();
        toastSuccess(response.message);
        toggle();
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  return (
    <>
      <Dialog
        open={open}
        onClose={toggle}
        fullWidth
        maxWidth="sm"
        scroll="paper"
      >
        <DialogTitle
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <Box>{dialogTitle}</Box>
          <IconButton
            aria-label="close"
            onClick={toggle}
            sx={{ color: (theme) => theme.palette.grey[500] }}
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent
          sx={{ pb: 8, px: { sx: 8, sm: 15 }, pt: { xs: 8, sm: 12.5 } }}
        >
          <form id="blog-form" onSubmit={handleSubmit(onSubmit)}>
            <Grid container spacing={4}>
              <Grid item xs={12}>
                <FormControl fullWidth>
                  <FormLabel required htmlFor="overview_pdf">
                    PDF
                  </FormLabel>
                  <FileInput
                    inputId="overview_pdf" // Corrected inputId to 'image'
                    accept=" .pdf"
                    onChange={(e) => handleFileChange(e)}
                    selectedFileName={selectedFileNames.overview_pdf}
                    error={Boolean(errors.overview_pdf)}
                  />
                  {errors.overview_pdf && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.overview_pdf.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>

              {/* <Grid item xs={12}>
                <FormControl fullWidth>
                  <FormLabel
                    required
                    htmlFor="status"
                    error={Boolean(errors.status)}
                  >
                    Status
                  </FormLabel>
                  <Controller
                    name="status"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <RadioGroup
                        row
                        name="status"
                        onChange={onChange}
                        value={value}
                      >
                        <FormControlLabel
                          value={"active"}
                          control={<Radio />}
                          label="Active"
                        />
                        <FormControlLabel
                          value={"inactive"}
                          control={<Radio />}
                          label="Inactive"
                        />
                      </RadioGroup>
                    )}
                  />
                  {errors.status && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.status.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid> */}
            </Grid>
          </form>
        </DialogContent>
        <DialogActions>
          <LoadingButton
            size="large"
            type="submit"
            form="blog-form"
            variant="contained"
            loading={loading}
          >
            Submit
          </LoadingButton>
          <Button size="large" variant="outlined" onClick={toggle}>
            Cancel
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default DialogOverviewDownload;
